import{_ as i,l as n,o as e,c as l,v as t,p as s,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"自动向量化","description":"","frontmatter":{"title":"自动向量化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/auto-vectorization.md","filePath":"cs/auto-vectorization.md","lastUpdated":1789023840000}'),h={name:"cs/auto-vectorization.md"};function E(u,a,_,m,A,f){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="自动向量化" tabindex="-1">自动向量化 <a class="header-anchor" href="#自动向量化" aria-label="Permalink to &quot;自动向量化&quot;">​</a></h1><div class="epigraph"><p>最内层循环若无环载依赖（或依赖距离足够），可把标量运算打成 SIMD。编译器要处理对齐、余数与控制流。</p><footer>—— 据 Allen and Kennedy 向量化；Nuzman 等 GCC 自动向量化；龙书对 SIMD 的讨论整理</footer></div><p>上一课<a href="/cs/loop-interchange-tiling">交换与分块</a>把最内层摆到连续地址。缺口是<strong>SIMD</strong>：一次算向量宽 \\(W\\) 个元素。本课钉依赖距离、对齐、掩码，不把 ISA 的全部 intrinsic 当目录。也不重写多面体。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若迭代 \\(i\\) 依赖 \\(i-1\\) 的结果（递推），则不能直接向量化。归约（求和）可用向量归约再横加，次序改变——浮点要许可。控制流：<code>if</code> 变成掩码或分路。缺口是<strong>把标量循环改写为向量 IR</strong>，不是手写 intrinsic。</p><p>对齐：剥到对齐，余数标量或掩码尾。</p><h3 id="向量化不是并行线程" tabindex="-1">向量化不是并行线程 <a class="header-anchor" href="#向量化不是并行线程" aria-label="Permalink to &quot;向量化不是并行线程&quot;">​</a></h3><p>SIMD 是单线程内的宽 ALU。OpenMP 多核是另一层。不要混。</p><p><span class="marginnote">Allen–Kennedy 经典向量机。Nuzman, Rosen, Zaks 等 GCC 自动向量化论文。LLVM LoopVectorize。本课不进 GPU SIMT 全模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分析最内层：访存仿射、依赖距离。生成：向量 load/store、宽 ALU、收尾。SCEV（标量进化）提供 IV 闭式——与<a href="/cs/strength-reduction-iv">归纳变量</a> 同一家族。</p>',11)),(e(),s(p,null,{default:o(()=>[c(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20INNER%5B%22%E6%9C%80%E5%86%85%E5%B1%82%22%5D%20--%3E%20DEP%5B%22%E6%97%A0%E7%8E%AF%E8%BD%BD%E4%BE%9D%E8%B5%96%3F%22%5D%0A%20%20DEP%20--%3E%20VEC%5B%22%E5%AE%BD%E8%BF%90%E7%AE%97%20%2B%20%E6%8E%A9%E7%A0%81%22%5D%0A%20%20VEC%20--%3E%20TAIL%5B%22%E4%BD%99%E6%95%B0%20%2F%20%E5%89%A5%E7%A6%BB%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与展开：常先按 \\(W\\) 展开再打包，或直接向量 IR。成本模型：是否值得（小行程则否）。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>别名：<code>restrict</code> 或运行时检查分出版本。间接访存（gather/scatter）有的 ISA 贵，可能放弃。不要向量化 <code>volatile</code>。</p><p>调试：向量体难对应源行，优化报告比静默失败重要。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 SLP（基本块超字）全文，点名它是另一向量化。后课默认：可证明独立的最内层可 SIMD。下一课多面体：统一依赖与变换。</p><p>也不把权重量化（神经网络 int8）当本课；那是大模型栏。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自动向量化：依赖允许则打 SIMD，处理对齐与余数。</li><li>归约与掩码改变次序或执行集，须语言许可。</li><li>成本模型决定是否做。</li><li>出处：Allen and Kennedy；Nuzman et al.；对照龙书。</li></ul>',9))])}const B=i(h,[["render",E]]);export{S as __pageData,B as default};
